import{_ as t,o,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const g=JSON.parse('{"title":"DataListView（数据视图列表）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/data-view/docs/README-DataListView.md","filePath":"docs/core/src/components/data-view/docs/README-DataListView.md"}'),i={name:"docs/core/src/components/data-view/docs/README-DataListView.md"};function s(c,e,n,r,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="datalistview-数据视图列表" tabindex="-1">DataListView（数据视图列表） <a class="header-anchor" href="#datalistview-数据视图列表" aria-label="Permalink to &quot;DataListView（数据视图列表）&quot;">​</a></h1><blockquote><p>卡片/自定义渲染的列表视图：外部传入数据与列配置，无请求、无分页；TableMain <code>customView</code> 模式的渲染载体。 <strong>自带网格能力</strong>：列数（断点表 / 流体）· item 间距 · 内置卡壳 · 瀑布流（opt-in）—— 消费方 [MUST NOT] 再手写 <code>:deep(.data-list-view){display:grid;…}</code>。 范式页：<code>apps/reference/src/pages/data-view/custom-view/Index.vue</code> ⚠️ 内部件：仅供 TableMain 内部 import，[MUST NOT] 对外导出（不进 core 顶层 export）</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：<code>TableMain</code> 的 <code>customView</code> 模式——自定义卡片视图替代标准表格渲染</li><li><strong>何时不用</strong>：标准表格用 <code>TableMain</code> / <code>ElTable</code>；DataListView 不直接对外消费</li><li>泛型 <code>&lt;T, F extends Record&lt;string, any&gt;&gt;</code>：行类型 / 注入上下文类型</li><li>数据契约：<code>data</code> 外部传入（当前页数据），组件无请求/分页逻辑</li><li><strong>网格能力与 <code>DataGridView</code> 同源</strong>：<code>gridColumns</code> 的断点语义<strong>逐字一致</strong>（共用 <code>resolveGridColumnsByBreakpoint</code>）， [MUST NOT] 在本路径另造一套 —— 两套断点心智会让同一页切 viewMode 时列数跳</li><li>接线：TableMain <code>customView.value ? markRaw(DataListView) : markRaw(ElTable)</code>；ListLayout 转发 <code>#custom-view-item</code> 插槽（类型 <code>DataListViewItemScope&lt;T&gt;</code>）</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>业务消费范式（经 TableMain <code>customView</code> 模式接入，<code>custom-view/Index.vue</code> 摘要）：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">TableMain</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :customView</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;customView&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :columns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;columns&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;api&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rowKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> #custom-view-item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{ fieldComponentMap, row, index, selected, toggleSelect }&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">component</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :is</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fieldComponentMap[&#39;name&#39;]&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :row</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;row&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;index&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">TableMain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>fieldComponentMap</code> 键规则：列 <code>prop</code> / <code>$type_index</code>（行号）/ <code>$type_selection</code>（选中框）；<code>type: &quot;expand&quot;</code> 跳过</li><li>字段组件经 <code>markRaw(defineComponent)</code>（name <code>&quot;DataViewField&quot;</code>，props <code>row</code> / <code>index</code> / <code>selected</code> / <code>toggleSelect</code>）产稳定组件，跨渲染不 remount</li><li>选中能力 <code>selectable</code> 开启后才有 <code>$type_selection</code> 键；选中变化走 <code>selectionChange</code>；<code>data</code> 引用变化（刷新）即清空选中</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>内部件不进顶层 export：仅供 TableMain 内部 import，[MUST NOT] 对外导出 / 全局注册 / install。</strong> 业务 [MUST] 走 <code>TableMain</code> <code>customView</code> 模式消费——本组件无请求/分页，<code>data</code> 须外部传入（当前页数据），脱离 TableMain 直接消费没有数据来源。</li><li><strong><code>maxHeight</code> / <code>minHeight</code>：默认 <code>undefined</code>（自然高度）即够用。</strong> 仅当限高滚动（<code>maxHeight</code> 传入容器 <code>overflowY: auto</code>）或配合 TableMain <code>fillHeight</code> 顶分页器到底（<code>minHeight</code>）才设。</li><li><strong><code>selectable</code>：默认 <code>false</code> 即够用。</strong> 仅当卡片需要选中/批量操作能力才开——开启后才有 <code>$type_selection</code> 键。</li><li><strong><code>gridColumns</code>：默认 <code>undefined</code> = 不成网格</strong>（单列流式，与本能力引入前一致）。要多列才传： 数字 = 定列数；对象 = el-col span 制断点表（与 <code>DataGridView</code> 同语义）；<code>{ min: N }</code> = <strong>流体列宽</strong> （<code>repeat(auto-fill, minmax(Npx, 1fr))</code>，列数由容器宽自然得出，不需要断点表）。</li><li><strong><code>gap</code>：默认取间距阶梯的**模块档**</strong>（<code>APP_LAYOUT_GAP_CONFIG.size × 密度 × 1</code>，默认 8）。 <code>grid</code> 的 gap 是<strong>卡与卡之间</strong> = 模块档的定义值，[MUST NOT] 在消费侧写死像素补偿。 🔴 <strong>与 <code>gridColumns</code> 正交</strong>：不成网格（默认）时同样有纵向间距，见下「间距无条件存在」。 要贴合传 <code>:gap=&quot;0&quot;</code>。</li><li><strong><code>card</code>：默认 <code>true</code></strong>（内置卡壳：border + radius + padding，全走 token）。 自带卡片视觉时传 <code>false</code> 关掉，[MUST NOT] 在自己的卡上再画一层边框叠上去。</li><li><strong><code>masonry</code>：默认 <code>false</code></strong>（瀑布流需要 JS 量高，按「需要 JS 就默认不开」的规则关着）。</li><li><strong><code>rowKey</code> / <code>columns</code> / <code>getRenderCtxParams</code> 必填契约</strong>：行唯一键、列配置、列 render 上下文缺一不可。</li><li><strong>完整能力演示</strong>（选中框列 + 行号列 + 字段列 + 操作列全接线）：<code>apps/reference/src/pages/data-view/custom-view/Index.vue</code>——能力展示，非推荐默认。</li></ul><h2 id="当前项跟随滚动-activescroll-默认开" tabindex="-1">当前项跟随滚动（<code>activeScroll</code>，默认开） <a class="header-anchor" href="#当前项跟随滚动-activescroll-默认开" aria-label="Permalink to &quot;当前项跟随滚动（`activeScroll`，默认开）&quot;">​</a></h2><p><code>activeId</code> 变化后把对应项滚进视口 —— 上/下一条导航、深链直达当前项等场景全靠它。</p><p>用 <code>nearest</code> 语义（<code>utils</code> 的 <code>domScrollIntoViewport</code>）：</p><ul><li><strong>已在视口内则零动作</strong> —— 用户自己滚着看时点某项不会被拽走；</li><li>避免「越级滚动」：原生默认 <code>block: &quot;start&quot;</code> 会把整个页面滚了。</li></ul><p>🔴 <strong>瞬时而非 smooth</strong>：这是<strong>跟随</strong>不是<strong>导航</strong>。本仓 <code>TabsTile</code> 自研 smooth 滚动 曾被 v-model 回流重渲染打断（真机复现），故此处 [MUST NOT] 默认 smooth。</p><p>关掉传 <code>:active-scroll=&quot;false&quot;</code>。</p><h2 id="网格能力-列数-间距-卡壳-瀑布流" tabindex="-1">网格能力（列数 / 间距 / 卡壳 / 瀑布流） <a class="header-anchor" href="#网格能力-列数-间距-卡壳-瀑布流" aria-label="Permalink to &quot;网格能力（列数 / 间距 / 卡壳 / 瀑布流）&quot;">​</a></h2><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 断点表：与 DataGridView 逐字同语义（24 栅格 span 制） --&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">TableMain</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :customView</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;customView&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :custom-view-props</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{ gridColumns: { xs: 24, sm: 12, md: 8, lg: 6 } }&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 流体列宽：列数由容器宽自然得出（消费方 2026-09-02 拍板过的形态） --&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">TableMain</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :custom-view-props</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{ gridColumns: { min: 189 } }&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>gridColumns</code> 形态</th><th>产出</th><th>何时用</th></tr></thead><tbody><tr><td>不传（默认）</td><td>不成网格（单列流式）</td><td>普通列表</td></tr><tr><td><code>number</code></td><td><code>repeat(N, 1fr)</code></td><td>列数固定</td></tr><tr><td><code>{ xs, sm, md, lg, xl }</code></td><td>按断点算列数（span 制，24 栅格；未配档回落 ≤ 当前断点最近一档）</td><td>要按视口分档</td></tr><tr><td><code>{ min: N }</code></td><td><code>repeat(auto-fill, minmax(Npx, 1fr))</code></td><td><strong>列数按容器宽流体</strong>、不想钉死</td></tr></tbody></table><p>🔴 <strong><code>{ min }</code> 这一档只有本组件有，<code>DataGridView</code> 没有</strong> —— 它按 <code>gridColumns</code> 把存量 <strong>chunk 成等长的行</strong>做虚拟化，而流体档的列数是浏览器算的、JS 拿不到 ⇒ chunk 无从下手。 这是实现约束不是遗漏，[MUST NOT] 为「对齐」把它硬塞进 <code>DataGridView</code>。</p><h3 id="间距无条件存在-与网格正交" tabindex="-1">间距无条件存在（与网格正交） <a class="header-anchor" href="#间距无条件存在-与网格正交" aria-label="Permalink to &quot;间距无条件存在（与网格正交）&quot;">​</a></h3><p><strong>间距是卡片列表的固有属性，不是网格的附属品</strong>（zc6ptn，甲方口径： 「无论是否多列展示、是否瀑布流，都不影响其 gap 的存在」）。</p><table tabindex="0"><thead><tr><th>形态</th><th>间距由谁出</th><th>值</th></tr></thead><tbody><tr><td>成网格（<code>gridColumns</code> 任一形态）</td><td>容器的 grid <code>gap</code></td><td><code>gap</code></td></tr><tr><td><strong>不成网格</strong>（默认）</td><td><strong>每项的 <code>margin-bottom</code></strong>（末项不下发）</td><td>同一个 <code>gap</code></td></tr><tr><td>瀑布流（<code>masonry</code>）</td><td>跨度里的 gap 分量（<code>ceil((卡高 + gap) / 行单位)</code>）</td><td>同一个 <code>gap</code></td></tr></tbody></table><p>三条路径<strong>共用同一个值</strong>，[MUST NOT] 另引第二个间距来源 （本仓已因此栽过：<code>--dc-core-content-gap</code> 与 gap 各随不同轴变动， 最松密度档出现「卡内 20 ≥ 外圈 20 &gt; 卡间 8」的乱序，那个变量已被明令废掉）。</p><p>🔴 <strong>不成网格时为何走 <code>margin</code> 而不是把容器改成 <code>flex</code> + <code>gap</code></strong>： ① 改 <code>display</code> 会连带改子项的布局语义（block → flex item），存量页面的可见变更面 远超「多出间距」；② <code>gap</code> 跨在盒<strong>之间</strong>、不计入 <code>clientHeight</code>，本仓在 <code>ViewLayout</code> 上栽过同一条（量不到 ⇒ 每页恒溢出一段）。</p><p>🔴 <strong>末项不下发 margin</strong>：块级流里末项的 <code>margin-bottom</code> 会与父盒底边折叠、<strong>穿透出去</strong> —— 既量不到又推开后邻，与上面那条坑同形。故本组件只给「非末项」下发。</p><p>⚠️ 这是一次<strong>可见变更</strong>：此前不配 <code>gridColumns</code> 的页面是零间距。 「就是要贴着」的消费方 [MUST] 显式传 <code>:gap=&quot;0&quot;</code>（阴性对照，出口有效）。</p><h3 id="内置卡壳-card-默认开" tabindex="-1">内置卡壳（<code>card</code>，默认开） <a class="header-anchor" href="#内置卡壳-card-默认开" aria-label="Permalink to &quot;内置卡壳（`card`，默认开）&quot;">​</a></h3><p>壳落在<strong>已有的包裹层</strong> <code>.data-list-view-item</code> 上（加 <code>is-card</code> 类），[MUST NOT] 另包一层： DOM 层级恒定 ⇒ 消费方写的 <code>:deep()</code> 选择器不会随 prop 变；瀑布流的跨度也「量谁写谁」。</p><p>壳<strong>只出面</strong>（border / radius / padding，全走 token）。 <code>.is-active</code> / <code>.is-selected</code> <strong>仍是空钩子</strong> —— 本族的立场从「[MUST NOT] 写死卡片视觉」 <strong>收窄为</strong>「[MUST NOT] 写死<strong>状态</strong>视觉」，两句话不再打架。</p><h3 id="空态占位自己成卡-v0-32-0" tabindex="-1">空态占位自己成卡（v0.32.0） <a class="header-anchor" href="#空态占位自己成卡-v0-32-0" aria-label="Permalink to &quot;空态占位自己成卡（v0.32.0）&quot;">​</a></h3><p>卡片态下容器<strong>不铺面</strong>（面与面不叠）。判据在<strong>有项</strong>时成立，<strong>没有项时没有 「项自带的卡片」来接替</strong> ⇒「暂无数据」直接浮在页面灰底上。 ⇒ <code>.data-list-view-empty</code> <strong>自己成卡</strong>（面 / 圆角 / 内呼吸，<strong>与卡壳同源</strong>）。</p><p>ℹ️ <strong>本组件不加 <code>max-width</code> 内缩</strong>（<code>InfiniteListView</code> 那侧有）：它的内缩由宿主 <code>TableMain</code> 的自持面 padding 给，而本组件<strong>看不到那份 padding</strong> —— 自己再加一层就是双重内缩，且无从判断该不该加。</p><h3 id="瀑布流-masonry-默认关" tabindex="-1">瀑布流（<code>masonry</code>，默认关） <a class="header-anchor" href="#瀑布流-masonry-默认关" aria-label="Permalink to &quot;瀑布流（`masonry`，默认关）&quot;">​</a></h3><p>开启后走 <code>grid-auto-rows: &lt;行单位&gt;</code> + 每项 <code>grid-row-end: span N</code>（N 由实测卡高算）， <strong>顺序仍是行优先（横向）</strong> —— 这正是纯 CSS <code>columns</code> 做不到的那点（它竖着填， 按时间/热度排的列表会被打乱）。</p><ul><li><strong>需要 JS ⇒ 默认关</strong>（规则：需要 JS 就默认不开）。</li><li>与 <code>gridColumns</code> 的 <code>{ min }</code> / 断点表都能叠。</li><li><strong>与 <code>DataGridView</code> 的瀑布流是两套机制</strong>（都提供，但前提不同）： 本条（分页路径）<strong>没有虚拟化</strong> ⇒ 可以<strong>直接量</strong>卡片实际高，消费方零额外输入； <code>DataGridView</code>（滚动路径）是虚拟化的 ⇒ 必须<strong>先算</strong>，故要消费方给 <code>estimateItemHeight</code>。 ⚠️ 两者<strong>不是「一个能一个不能」</strong> —— 早期文档说「天然冲突」措辞偏强， 准确说法是后者<strong>需要「高度可预先计算」这一前提</strong>。</li><li>量不到高度时每项退<strong>兜底跨度</strong>（CSS 给的），表现为「不够好看」而<strong>不会重叠</strong>—— 增强失败 [MUST NOT] 变成布局坏掉。</li><li><strong>0 条时不铺轨道</strong>：空态按非瀑布流形态完整显示（否则空态占位只占一条行单位轨道、被裁成一条缝）。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>data</code></td><td><code>T[]</code>（必填）</td><td>无</td><td>当前页数据，外部传入，组件无请求/分页逻辑</td></tr><tr><td><code>rowKey</code></td><td><code>Extract&lt;keyof T, string&gt; | ((row: T) =&gt; string)</code>（必填）</td><td>无</td><td>行唯一键：键名或函数，内部统一 String 化</td></tr><tr><td><code>columns</code></td><td><code>DataViewColumn&lt;T&gt;[]</code>（必填）</td><td>无</td><td>列配置（Pick 自 ElTableColumnProps 的 <code>prop</code> / <code>label</code> / <code>type</code> / <code>render</code>），内部归一为 <code>fieldComponentMap</code></td></tr><tr><td><code>maxHeight</code></td><td><code>number</code></td><td><code>undefined</code></td><td>传入时容器 <code>overflowY: auto</code> 限高滚动</td></tr><tr><td><code>minHeight</code></td><td><code>number</code></td><td><code>undefined</code></td><td>传入时撑满至此高（配合 TableMain <code>fillHeight</code> 顶分页器到底）</td></tr><tr><td><code>gridColumns</code></td><td><code>number | Partial&lt;Record&lt;Breakpoint, number&gt;&gt; | { min: number }</code></td><td><code>undefined</code></td><td>列数：数字 = 定列数；对象 = el-col span 制断点表（与 <code>DataGridView</code> 同语义）；<code>{ min }</code> = 流体列宽 <code>repeat(auto-fill, minmax(Npx,1fr))</code>。不传 = 不成网格</td></tr><tr><td><code>gap</code></td><td><code>number</code></td><td>模块档（默认 <code>8</code>）</td><td>item 间距（px）。缺省取间距阶梯模块档，随 gap 基数与密度缩放。<strong>与 <code>gridColumns</code> 正交</strong>：不成网格时走每项 <code>margin-bottom</code>、同值</td></tr><tr><td><code>card</code></td><td><code>boolean</code></td><td><code>true</code></td><td>内置卡壳（border/radius/padding，走 token；落在 <code>.data-list-view-item</code> 上）。自带卡片视觉时关掉</td></tr><tr><td><code>masonry</code></td><td><code>boolean</code></td><td><code>false</code></td><td>瀑布流装箱（需要 JS 量高，故默认关）。顺序仍行优先</td></tr><tr><td><code>selectable</code></td><td><code>boolean</code></td><td><code>false</code></td><td>启用选中能力</td></tr><tr><td><code>getRenderCtxParams</code></td><td><code>() =&gt; Pick&lt;TableColumnDefaultScope&lt;T, F&gt;, &quot;injectInfo&quot; | &quot;exposeInfo&quot;&gt;</code>（必填）</td><td>无</td><td>列 render 上下文（必填契约）</td></tr></tbody></table><h3 id="v-model" tabindex="-1">v-model <a class="header-anchor" href="#v-model" aria-label="Permalink to &quot;v-model&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名</th><th>type</th><th>语义</th></tr></thead><tbody><tr><td><code>activeId</code></td><td><code>string | number | undefined</code></td><td><strong>「当前项」唯一键</strong>（= 用户点击/激活的那一条；[MUST NOT] 与勾选 <code>selected</code> 混同）。点击任一项即写入。<code>string</code> / <code>number</code> 两种都是一等公民：出口值<strong>保原始类型</strong>（<code>rowKey</code> 为字段名时即 <code>row[rowKey]</code>，数字 id 出数字），外部用另一种类型写入也命中（比对内部 <code>String()</code> 归一，且保留调用方原值）</td></tr><tr><td><code>activeData</code></td><td><code>T | undefined</code></td><td>当前项对应的<strong>列表数据原样</strong>。与 <code>activeId</code> <strong>同生同灭</strong>：<code>activeId</code> 有值 ⇒ 本值必有值；<code>data</code> 刷新后当前项不在新数据内 → 两者一并清空；外部写入不在 <code>data</code> 内的 id → 忽略 + <code>console.warn</code>（不清空既有选中）</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>语义</th></tr></thead><tbody><tr><td><code>selectionChange</code></td><td><code>rows: T[]</code></td><td>选中项变更（勾选语义，与 active 无关）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#item</code></td><td><code>DataListViewItemScope&lt;T&gt;</code>（<code>fieldComponentMap</code> / <code>row</code> / <code>index</code> / <code>selected</code> / <code>toggleSelect</code> / <code>active</code> / <code>setActive</code>）</td><td>单项渲染（customView 卡片内容）。<code>active</code> = 是否当前项、<code>setActive()</code> = 设为当前项（等价点击该项）</td></tr><tr><td><code>#empty</code></td><td>无</td><td>空态（默认 <code>&lt;el-empty /&gt;</code>，消费方可覆写）</td></tr></tbody></table><h3 id="expose-datalistviewinstance-tableinstance-对齐" tabindex="-1">Expose（<code>DataListViewInstance</code> = TableInstance 对齐） <a class="header-anchor" href="#expose-datalistviewinstance-tableinstance-对齐" aria-label="Permalink to &quot;Expose（`DataListViewInstance` = TableInstance 对齐）&quot;">​</a></h3><p>实际实现 5 个：<code>clearSelection</code> / <code>getSelectionRows</code> / <code>toggleRowSelection</code> / <code>toggleAllSelection</code> / <code>columns</code>。</p><p>其余 10 个方法（<code>toggleRowExpansion</code> / <code>setCurrentRow</code> / <code>clearSort</code> / <code>clearFilter</code> / <code>doLayout</code> / <code>sort</code> / <code>scrollTo</code> / <code>setScrollTop</code> / <code>setScrollLeft</code> / <code>updateKeyChildren</code>）经 utils 填「not supported」抛错桩——调用即抛错，勿依赖。</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>不对外导出</strong>：本组件 [MUST NOT] 对外导出 / 全局注册 / 提供 install 插件；消费方 [MUST] 走 <code>TableMain</code> <code>customView</code> 模式</li><li><strong>无请求/分页</strong>：<code>data</code> 须外部传入（当前页数据），勿期待组件内部取数</li><li><strong>刷新清选中</strong>：<code>data</code> 引用变化即清空选中——跨页 / 刷新后选中状态不保留</li><li><strong>未实现方法抛错</strong>：Expose 面与 TableInstance 对齐但 10 个方法为「not supported」桩（表格特有行为在自定义视图无意义）——含 <code>setCurrentRow</code>，故 TableMain 在 <code>customView</code> 态 [MUST NOT] 调它同步高亮（active 由本组件自持）</li><li><strong><code>.is-active</code> / <code>.is-selected</code> 是空钩子类</strong>：本族 [MUST NOT] 写死<strong>状态</strong>视觉，选中 / 当前项的样式由消费方覆写。 ⚠️ 这条立场 2026-09-17 <strong>收窄过</strong>：内置卡壳（<code>card</code>，默认开）只出<strong>面</strong>（border/radius/padding）， 状态视觉仍是空钩子 —— [MUST NOT] 拿旧话「不写死卡片视觉」去否掉卡壳，也 [MUST NOT] 反过来在钩子里写死状态色</li><li><strong>列键依赖归一规则</strong>：消费 <code>fieldComponentMap</code> 只用 <code>prop</code> / <code>$type_index</code> / <code>$type_selection</code> 三系键，<code>type: &quot;expand&quot;</code> 列不产出</li></ul><h2 id="datalistviewitem-列表项容器" tabindex="-1">DataListViewItem（列表项容器） <a class="header-anchor" href="#datalistviewitem-列表项容器" aria-label="Permalink to &quot;DataListViewItem（列表项容器）&quot;">​</a></h2><p>由 DataListView 内部 <code>v-for</code> 使用的列表项容器；消费方一般不直接使用。</p><h3 id="props-1" tabindex="-1">Props <a class="header-anchor" href="#props-1" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>selected</code></td><td><code>boolean</code>（必填）</td><td>无</td><td>是否选中（勾选语义，由 DataListView 传入）→ <code>.is-selected</code></td></tr><tr><td><code>active</code></td><td><code>boolean</code></td><td><code>false</code></td><td>是否为「当前项」（active，与勾选无关）→ <code>.is-active</code></td></tr><tr><td><code>card</code></td><td><code>boolean</code></td><td><code>false</code></td><td>是否套内置卡壳 → <code>.is-card</code>（border/radius/padding 走 token）。由 <code>DataListView</code> 下发，默认值以它为准</td></tr><tr><td><code>spanRows</code></td><td><code>number</code></td><td><code>undefined</code></td><td>瀑布流跨度（<code>grid-row-end: span N</code>）；仅 <code>masonry</code> 开启时由 <code>DataListView</code> 下发</td></tr><tr><td><code>flowGap</code></td><td><code>number</code></td><td><code>undefined</code></td><td><strong>不成网格时的纵向间距</strong>（<code>margin-bottom</code>）；由 <code>DataListView</code> 按「非末项 且 不成网格」条件下发，成网格时恒 <code>0</code>（间距归 grid 的 <code>gap</code>，[MUST NOT] 叠加）</td></tr></tbody></table><h3 id="emits-expose" tabindex="-1">Emits / Expose <a class="header-anchor" href="#emits-expose" aria-label="Permalink to &quot;Emits / Expose&quot;">​</a></h3><p>无</p><h3 id="slots-1" tabindex="-1">Slots <a class="header-anchor" href="#slots-1" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#default</code></td><td>无</td><td>项内容</td></tr></tbody></table><h3 id="定位注释-vue-头" tabindex="-1">定位注释（.vue 头） <a class="header-anchor" href="#定位注释-vue-头" aria-label="Permalink to &quot;定位注释（.vue 头）&quot;">​</a></h3><ul><li>承载选中 / 当前项 class 钩子 + 可选卡壳（<code>card</code>）+ 项内容插槽</li><li>[MUST NOT] 写死<strong>状态</strong>视觉（<code>.is-active</code> / <code>.is-selected</code> 归消费方）；卡壳只出面，不碰状态</li><li>[MUST NOT] 内置选中状态机</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>宿主：<code>TableMain</code>（table 族，<code>customView</code> 模式）；<code>ListLayout</code>（转发 <code>#custom-view-item</code>）</li><li>内部件：<code>DataListViewItem</code>（本文件上文）</li><li>类型：<code>DataViewColumn&lt;T&gt;</code> / <code>DataListViewItemScope&lt;T&gt;</code>（data-view types.ts）</li><li>范式页：<code>apps/reference/src/pages/data-view/custom-view/Index.vue</code></li></ul>',64)])])}const k=t(i,[["render",s]]);export{g as __pageData,k as default};
